//! The state of one queue and the rules that only concern that queue.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};

pub const MAX_QUEUES: usize = 1000;
pub const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW_SECONDS: u64 = 300;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

/// The attributes of a queue. The dead-letter pair is one `Option` because
/// both halves are set or both are unset.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum State {
    Delayed,
    InFlight,
    Visible,
}

#[derive(Clone, Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    pub group_id: Option<String>,
    pub sequence_number: Option<u64>,
    /// The message is visible from this time on; before it, it is in flight
    /// if it has a receipt handle and delayed otherwise.
    pub visible_at: u64,
    pub receipt_handle: Option<u64>,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        if now >= self.visible_at {
            State::Visible
        } else if self.receipt_handle.is_some() {
            State::InFlight
        } else {
            State::Delayed
        }
    }
}

struct Sent {
    at: u64,
    message_id: u64,
    sequence_number: u64,
}

/// What a `receive` call did: the messages handed out, and the messages
/// that left the queue for its dead-letter queue.
pub struct Received {
    pub delivered: Vec<Message>,
    pub dead: Vec<Message>,
}

pub struct Queue {
    pub attributes: Attributes,
    /// Keyed by an arrival counter, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    /// `(sent_at, key)` of every message, so retention only looks at the oldest.
    by_sent_at: BTreeSet<(u64, u64)>,
    /// Latest receipt handle of each message that has one, to its key.
    by_handle: HashMap<u64, u64>,
    sent_ids: HashMap<String, Sent>,
    next_key: u64,
    next_sequence_number: u64,
}

impl Queue {
    pub fn new(attributes: Attributes) -> Self {
        Self {
            attributes,
            messages: BTreeMap::new(),
            by_sent_at: BTreeSet::new(),
            by_handle: HashMap::new(),
            sent_ids: HashMap::new(),
            next_key: 0,
            next_sequence_number: 1,
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn is_empty(&self) -> bool {
        self.messages.is_empty()
    }

    pub fn counts(&self, now: u64) -> [usize; 3] {
        let mut counts = [0; 3];
        for message in self.messages.values() {
            match message.state(now) {
                State::Visible => counts[0] += 1,
                State::InFlight => counts[1] += 1,
                State::Delayed => counts[2] += 1,
            }
        }
        counts
    }

    /// Removes the messages whose retention has run out.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.attributes.retention_seconds);
        while let Some(&(sent_at, key)) = self.by_sent_at.first() {
            if sent_at + retention > now {
                break;
            }
            self.remove(key);
        }
    }

    /// Adds `message` at the end of the queue and returns its sequence
    /// number if this is a FIFO queue.
    pub fn push(&mut self, mut message: Message) -> Option<u64> {
        let sequence_number = self.attributes.fifo.then(|| {
            let n = self.next_sequence_number;
            self.next_sequence_number += 1;
            n
        });
        message.sequence_number = sequence_number;
        let key = self.next_key;
        self.next_key += 1;
        self.by_sent_at.insert((message.sent_at, key));
        if let Some(handle) = message.receipt_handle {
            self.by_handle.insert(handle, key);
        }
        self.messages.insert(key, message);
        sequence_number
    }

    /// Adds a message that arrives from another queue's dead-letter move.
    pub fn push_dead(&mut self, mut message: Message, now: u64) {
        message.receive_count = 0;
        message.first_received_at = None;
        message.visible_at = now;
        message.receipt_handle = None;
        self.push(message);
        self.expire(now);
    }

    fn remove(&mut self, key: u64) -> Option<Message> {
        let message = self.messages.remove(&key)?;
        self.by_sent_at.remove(&(message.sent_at, key));
        if let Some(handle) = message.receipt_handle {
            self.by_handle.remove(&handle);
        }
        Some(message)
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.by_sent_at.clear();
        self.by_handle.clear();
    }

    /// The message and sequence number of an earlier send with the same
    /// deduplication id, if its window is still open.
    pub fn duplicate_of(&self, dedup_id: &str, now: u64) -> Option<(u64, u64)> {
        let sent = self.sent_ids.get(dedup_id)?;
        (now - sent.at < DEDUP_WINDOW_SECONDS).then_some((sent.message_id, sent.sequence_number))
    }

    pub fn record_sent(&mut self, dedup_id: String, now: u64, message_id: u64, sequence_number: u64) {
        let sent = Sent {
            at: now,
            message_id,
            sequence_number,
        };
        self.sent_ids.insert(dedup_id, sent);
    }

    /// Delivers up to `max` messages and moves the exhausted ones out.
    /// `issued_handles` counts the receipt handles issued so far, process-wide.
    pub fn receive(&mut self, now: u64, max: usize, visibility: u32, issued_handles: &mut u64) -> Received {
        let max_receive_count = self.attributes.dead_letter.as_ref().map(|d| d.max_receive_count);
        // Groups that still have an earlier message in the queue.
        let mut occupied: HashSet<&str> = HashSet::new();
        let mut deliver = Vec::new();
        let mut dead = Vec::new();
        for (&key, message) in &self.messages {
            if deliver.len() == max {
                break;
            }
            let group = message.group_id.as_deref();
            let eligible =
                message.state(now) == State::Visible && group.is_none_or(|g| !occupied.contains(g));
            if eligible && max_receive_count.is_some_and(|limit| message.receive_count >= limit) {
                dead.push(key);
                continue;
            }
            if let Some(group) = group {
                occupied.insert(group);
            }
            if eligible {
                deliver.push(key);
            }
        }

        let dead = dead.into_iter().filter_map(|key| self.remove(key)).collect();
        let mut delivered = Vec::with_capacity(deliver.len());
        for key in deliver {
            *issued_handles += 1;
            let handle = *issued_handles;
            let message = self.messages.get_mut(&key).expect("key was found in this queue");
            if let Some(old) = message.receipt_handle.replace(handle) {
                self.by_handle.remove(&old);
            }
            self.by_handle.insert(handle, key);
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            message.visible_at = now + u64::from(visibility);
            delivered.push(message.clone());
        }
        Received { delivered, dead }
    }

    /// The key of the message that is in flight under exactly this handle.
    fn in_flight(&self, handle: u64, now: u64) -> Option<u64> {
        let key = *self.by_handle.get(&handle)?;
        let message = self.messages.get(&key)?;
        (message.state(now) == State::InFlight).then_some(key)
    }

    /// Returns whether `handle` was the usable handle of a message, and
    /// deletes that message if so.
    pub fn delete_in_flight(&mut self, handle: u64, now: u64) -> bool {
        match self.in_flight(handle, now) {
            Some(key) => self.remove(key).is_some(),
            None => false,
        }
    }

    pub fn change_visibility(&mut self, handle: u64, now: u64, timeout: u32) -> bool {
        match self.in_flight(handle, now) {
            Some(key) => {
                if let Some(message) = self.messages.get_mut(&key) {
                    message.visible_at = now + u64::from(timeout);
                }
                true
            }
            None => false,
        }
    }
}
EOF
