//! Typed access to the members of a command, with the protocol's rules for
//! `null`, integers and error codes.

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Code, Error, Result};

#[derive(Clone, Copy)]
pub enum Charset {
    Any,
    /// `A-Z a-z 0-9 _ -`
    Identifier,
}

pub fn is_identifier_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

pub struct Params<'a>(pub &'a Map<String, Value>);

impl<'a> Params<'a> {
    /// A member's value, with `null` treated as absent.
    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(Error::new(Code::MissingParameter, format!("{name} is required"))),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name).map(|v| as_string(name, v)).transpose()
    }

    /// A string whose length (in bytes) is in `len` and whose characters are in `charset`.
    pub fn text(&self, name: &str, len: RangeInclusive<usize>, charset: Charset) -> Result<Option<&'a str>> {
        let Some(s) = self.string(name)? else {
            return Ok(None);
        };
        let chars_ok = match charset {
            Charset::Any => true,
            Charset::Identifier => s.chars().all(is_identifier_char),
        };
        if !len.contains(&s.len()) || !chars_ok {
            return Err(invalid(name, "has a length or characters that are not allowed"));
        }
        Ok(Some(s))
    }

    pub fn required_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?
            .ok_or_else(|| Error::new(Code::MissingParameter, format!("{name} is required")))
    }

    pub fn int(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        let Some(value) = self.get(name) else {
            return Ok(None);
        };
        // `as_i64` is `None` for fractions, exponents and numbers beyond i64.
        let n = value
            .as_i64()
            .ok_or_else(|| invalid(name, "must be an integer"))?;
        u32::try_from(n)
            .ok()
            .filter(|n| range.contains(n))
            .map(Some)
            .ok_or_else(|| invalid(name, format!("must be between {} and {}", range.start(), range.end())))
    }

    pub fn required_int(&self, name: &str, range: RangeInclusive<u32>) -> Result<u32> {
        self.int(name, range)?
            .ok_or_else(|| Error::new(Code::MissingParameter, format!("{name} is required")))
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| v.as_bool().ok_or_else(|| invalid(name, "must be a boolean")))
            .transpose()
    }

    pub fn object(&self, name: &str) -> Result<Option<Params<'a>>> {
        self.get(name)
            .map(|v| {
                v.as_object()
                    .map(Params)
                    .ok_or_else(|| invalid(name, "must be an object"))
            })
            .transpose()
    }
}

fn as_string<'a>(name: &str, value: &'a Value) -> Result<&'a str> {
    value.as_str().ok_or_else(|| invalid(name, "must be a string"))
}

fn invalid(name: &str, problem: impl std::fmt::Display) -> Error {
    Error::new(Code::InvalidParameterValue, format!("{name} {problem}"))
}
