//! The commands: parsing a line, applying it to the state, building the response.

use std::collections::BTreeMap;

use serde_json::{Map, Value, json};

use crate::error::{Code, Error, Result};
use crate::params::{Charset, Params, is_identifier_char};
use crate::queue::{Attributes, DeadLetter, MAX_MESSAGES, MAX_QUEUES, Message, Queue};

type Output = Map<String, Value>;

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

/// The attributes present in a request, before defaults or merging.
#[derive(Default)]
struct AttributeUpdate {
    visibility_timeout: Option<u32>,
    delay_seconds: Option<u32>,
    retention_seconds: Option<u32>,
    fifo: Option<bool>,
    content_based_deduplication: Option<bool>,
    dead_letter_queue: Option<String>,
    max_receive_count: Option<u32>,
}

impl AttributeUpdate {
    fn parse(attributes: Option<Params<'_>>) -> Result<Self> {
        let Some(p) = attributes else {
            return Ok(Self::default());
        };
        for (name, value) in p.0 {
            if !value.is_null() && !ATTRIBUTE_NAMES.contains(&name.as_str()) {
                return Err(Error::new(
                    Code::InvalidParameterValue,
                    format!("unknown attribute {name}"),
                ));
            }
        }
        Ok(Self {
            visibility_timeout: p.int("VisibilityTimeout", 0..=43200)?,
            delay_seconds: p.int("DelaySeconds", 0..=900)?,
            retention_seconds: p.int("RetentionSeconds", 60..=1_209_600)?,
            fifo: p.boolean("Fifo")?,
            content_based_deduplication: p.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: p.int("MaxReceiveCount", 1..=1000)?,
        })
    }

    /// The dead-letter configuration, which must be given whole or not at all.
    fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => Ok(Some(DeadLetter {
                queue: queue.clone(),
                max_receive_count,
            })),
            (None, None) => Ok(None),
            _ => Err(Error::new(
                Code::InvalidParameterValue,
                "DeadLetterQueue and MaxReceiveCount must be given together",
            )),
        }
    }
}

fn valid_queue_name(name: &str) -> bool {
    let (base, max_len) = match name.strip_suffix(".fifo") {
        Some(base) => (base, 75),
        None => (name, 80),
    };
    (1..=max_len).contains(&base.len()) && base.chars().all(is_identifier_char)
}

fn queue_missing(name: &str) -> Error {
    Error::new(Code::QueueDoesNotExist, format!("queue {name:?} does not exist"))
}

fn empty() -> Result<Output> {
    Ok(Output::new())
}

/// Parses `r-<n>` exactly as issued; `issued` is how many handles exist.
fn parse_handle(handle: &str, issued: u64) -> Option<u64> {
    let digits = handle.strip_prefix("r-")?;
    let n: u64 = digits.parse().ok()?;
    (n.to_string() == digits && (1..=issued).contains(&n)).then_some(n)
}

#[derive(Default)]
pub struct Service {
    now: u64,
    queues: BTreeMap<String, Queue>,
    messages_accepted: u64,
    handles_issued: u64,
}

impl Service {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one input line (without its newline) and returns the response line.
    pub fn handle_line(&mut self, line: &[u8]) -> String {
        let response = match self.run(line) {
            Ok(mut members) => {
                members.insert("ok".into(), Value::Bool(true));
                Value::Object(members)
            }
            Err(e) => json!({"ok": false, "error": {"code": e.code.as_str(), "message": e.message}}),
        };
        response.to_string()
    }

    fn run(&mut self, line: &[u8]) -> Result<Output> {
        let bad = |what: &str| Error::new(Code::InvalidRequest, what.to_owned());
        let text = std::str::from_utf8(line).map_err(|_| bad("line is not valid UTF-8"))?;
        let Ok(Value::Object(members)) = serde_json::from_str(text) else {
            return Err(bad("line is not a JSON object"));
        };
        let p = Params(&members);
        let Some(Value::String(command)) = members.get("Command") else {
            return Err(bad("Command must be a string"));
        };
        match command.as_str() {
            "CreateQueue" => self.create_queue(&p),
            "SetQueueAttributes" => self.set_queue_attributes(&p),
            "GetQueueAttributes" => self.get_queue_attributes(&p),
            "ListQueues" => self.list_queues(&p),
            "DeleteQueue" => self.delete_queue(&p),
            "PurgeQueue" => self.purge_queue(&p),
            "Tick" => self.tick(&p),
            "SendMessage" => self.send_message(&p),
            "ReceiveMessage" => self.receive_message(&p),
            "DeleteMessage" => self.settle(&p, None),
            "ChangeMessageVisibility" => self.settle(&p, Some(())),
            _ => Err(bad("unknown command")),
        }
    }

    /// The queue named `name`, with expired messages already removed.
    fn queue_mut(&mut self, name: &str) -> Result<&mut Queue> {
        let now = self.now;
        let queue = self.queues.get_mut(name).ok_or_else(|| queue_missing(name))?;
        queue.expire(now);
        Ok(queue)
    }

    fn create_queue(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        if !valid_queue_name(name) {
            return Err(Error::new(Code::QueueNameInvalid, format!("{name:?} is not a valid queue name")));
        }
        let update = AttributeUpdate::parse(p.object("Attributes")?)?;
        let fifo = update.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(
                Code::QueueNameInvalid,
                "the .fifo suffix and the Fifo attribute must agree",
            ));
        }
        let content_based = update.content_based_deduplication.unwrap_or(false);
        if content_based && !fifo {
            return Err(Error::new(
                Code::InvalidParameterValue,
                "ContentBasedDeduplication needs a FIFO queue",
            ));
        }
        let dead_letter = update.dead_letter()?;
        let defaults = Attributes::default();
        let attributes = Attributes {
            visibility_timeout: update.visibility_timeout.unwrap_or(defaults.visibility_timeout),
            delay_seconds: update.delay_seconds.unwrap_or(defaults.delay_seconds),
            retention_seconds: update.retention_seconds.unwrap_or(defaults.retention_seconds),
            fifo,
            content_based_deduplication: content_based,
            dead_letter,
        };
        if let Some(existing) = self.queues.get(name) {
            return if existing.attributes == attributes {
                empty()
            } else {
                Err(Error::new(
                    Code::QueueAlreadyExists,
                    format!("queue {name:?} exists with different attributes"),
                ))
            };
        }
        if let Some(dead) = &attributes.dead_letter {
            let target = self.queues.get(&dead.queue).ok_or_else(|| queue_missing(&dead.queue))?;
            if target.attributes.fifo != fifo {
                return Err(Error::new(
                    Code::InvalidParameterValue,
                    "the dead-letter queue must be of the same type",
                ));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(attributes));
        empty()
    }

    fn set_queue_attributes(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.required_string("QueueName")?;
        let update = AttributeUpdate::parse(p.object("Attributes")?)?;
        let now = self.now;
        let fifo = self.queue_mut(name)?.attributes.fifo;
        if update.fifo.is_some() {
            return Err(Error::new(Code::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if update.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::new(
                Code::InvalidParameterValue,
                "ContentBasedDeduplication needs a FIFO queue",
            ));
        }
        let dead_letter = update.dead_letter()?;
        if let Some(dead) = &dead_letter {
            let target = self.queues.get(&dead.queue).ok_or_else(|| queue_missing(&dead.queue))?;
            if dead.queue == name || target.attributes.fifo != fifo {
                return Err(Error::new(
                    Code::InvalidParameterValue,
                    "the dead-letter queue must be another queue of the same type",
                ));
            }
        }
        let queue = self.queue_mut(name)?;
        let a = &mut queue.attributes;
        a.visibility_timeout = update.visibility_timeout.unwrap_or(a.visibility_timeout);
        a.delay_seconds = update.delay_seconds.unwrap_or(a.delay_seconds);
        a.retention_seconds = update.retention_seconds.unwrap_or(a.retention_seconds);
        a.content_based_deduplication = update
            .content_based_deduplication
            .unwrap_or(a.content_based_deduplication);
        if dead_letter.is_some() {
            a.dead_letter = dead_letter;
        }
        queue.expire(now);
        empty()
    }

    fn get_queue_attributes(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let a = &queue.attributes;
        let mut attributes = json!({
            "VisibilityTimeout": a.visibility_timeout,
            "DelaySeconds": a.delay_seconds,
            "RetentionSeconds": a.retention_seconds,
            "Fifo": a.fifo,
            "ContentBasedDeduplication": a.content_based_deduplication,
        });
        if let Some(dead) = &a.dead_letter {
            attributes["DeadLetterQueue"] = json!(dead.queue);
            attributes["MaxReceiveCount"] = json!(dead.max_receive_count);
        }
        let [visible, in_flight, delayed] = queue.counts(now);
        Ok(output(json!({
            "Attributes": attributes,
            "Counts": {"Visible": visible, "InFlight": in_flight, "Delayed": delayed},
        })))
    }

    fn list_queues(&mut self, p: &Params) -> Result<Output> {
        let prefix = p.string("Prefix")?.unwrap_or("");
        let names: Vec<&String> = self.queues.keys().filter(|n| n.starts_with(prefix)).collect();
        Ok(output(json!({"QueueNames": names})))
    }

    fn delete_queue(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        self.queue_mut(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.attributes.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.attributes.dead_letter = None;
            }
        }
        empty()
    }

    fn purge_queue(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        self.queue_mut(p.required_string("QueueName")?)?.purge();
        empty()
    }

    fn tick(&mut self, p: &Params) -> Result<Output> {
        p.require(&["Seconds"])?;
        self.now += u64::from(p.required_int("Seconds", 0..=1_209_600)?);
        Ok(output(json!({"Now": self.now})))
    }

    fn send_message(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName", "Body"])?;
        let name = p.required_string("QueueName")?;
        let body = p.text("Body", 1..=1024, Charset::Any)?.unwrap_or_default();
        let delay = p.int("DelaySeconds", 0..=900)?;
        let group_id = p.text("GroupId", 1..=128, Charset::Identifier)?;
        let dedup_id = p.text("DeduplicationId", 1..=128, Charset::Identifier)?;
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let a = &queue.attributes;
        let fifo = a.fifo;
        if (!fifo && (group_id.is_some() || dedup_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(
                Code::UnsupportedOperation,
                "GroupId and DeduplicationId need a FIFO queue, DelaySeconds a standard queue",
            ));
        }
        let missing = |what: &str| Error::new(Code::MissingParameter, format!("{what} is required"));
        let mut dedup_key = None;
        if fifo {
            if group_id.is_none() {
                return Err(missing("GroupId"));
            }
            if dedup_id.is_none() && !a.content_based_deduplication {
                return Err(missing("DeduplicationId"));
            }
            let key = dedup_id.unwrap_or(body);
            if let Some((message_id, sequence_number)) = queue.duplicate_of(key, now) {
                return Ok(output(json!({
                    "MessageId": format!("m-{message_id}"),
                    "SequenceNumber": sequence_number,
                })));
            }
            dedup_key = Some(key.to_owned());
        }
        if queue.len() >= MAX_MESSAGES {
            return Err(Error::new(Code::LimitExceeded, "the queue is full"));
        }
        self.messages_accepted += 1;
        let id = self.messages_accepted;
        let delay = delay.unwrap_or(queue.attributes.delay_seconds);
        let sequence_number = queue.push(Message {
            id,
            body: body.to_owned(),
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group_id: group_id.map(str::to_owned),
            sequence_number: None,
            visible_at: now + u64::from(delay),
            receipt_handle: None,
        });
        let mut result = json!({"MessageId": format!("m-{id}")});
        if let (Some(key), Some(sequence_number)) = (dedup_key, sequence_number) {
            queue.record_sent(key, now, id, sequence_number);
            result["SequenceNumber"] = json!(sequence_number);
        }
        Ok(output(result))
    }

    fn receive_message(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let max = p.int("MaxMessages", 1..=10)?.unwrap_or(1);
        let visibility = p.int("VisibilityTimeout", 0..=43200)?;
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let visibility = visibility.unwrap_or(queue.attributes.visibility_timeout);
        let dead_letter = queue.attributes.dead_letter.as_ref().map(|d| d.queue.clone());
        let received = queue.receive(now, max as usize, visibility, &mut self.handles_issued);
        let fifo = queue.attributes.fifo;
        if let Some(target) = dead_letter.and_then(|n| self.queues.get_mut(&n)) {
            target.expire(now);
            for message in received.dead {
                target.push_dead(message, now);
            }
        }
        let messages: Vec<Value> = received
            .delivered
            .iter()
            .map(|m| {
                let mut v = json!({
                    "MessageId": format!("m-{}", m.id),
                    "ReceiptHandle": format!("r-{}", m.receipt_handle.unwrap_or_default()),
                    "Body": m.body,
                    "ReceiveCount": m.receive_count,
                    "SentAt": m.sent_at,
                    "FirstReceivedAt": m.first_received_at,
                });
                if fifo {
                    v["GroupId"] = json!(m.group_id);
                    v["SequenceNumber"] = json!(m.sequence_number);
                }
                v
            })
            .collect();
        Ok(output(json!({"Messages": messages})))
    }

    /// `DeleteMessage` when `change` is `None`, else `ChangeMessageVisibility`.
    fn settle(&mut self, p: &Params, change: Option<()>) -> Result<Output> {
        let mut required = vec!["QueueName", "ReceiptHandle"];
        if change.is_some() {
            required.push("VisibilityTimeout");
        }
        p.require(&required)?;
        let name = p.required_string("QueueName")?;
        let handle = p.required_string("ReceiptHandle")?;
        let timeout = match change {
            Some(()) => Some(p.required_int("VisibilityTimeout", 0..=43200)?),
            None => None,
        };
        let now = self.now;
        let issued = self.handles_issued;
        let queue = self.queue_mut(name)?;
        let handle = parse_handle(handle, issued)
            .ok_or_else(|| Error::new(Code::ReceiptHandleInvalid, "this handle was never issued"))?;
        let done = match timeout {
            Some(timeout) => queue.change_visibility(handle, now, timeout),
            None => queue.delete_in_flight(handle, now),
        };
        if done {
            empty()
        } else {
            Err(Error::new(Code::ReceiptHandleExpired, "this handle is no longer usable"))
        }
    }
}

fn output(value: Value) -> Output {
    match value {
        Value::Object(members) => members,
        _ => unreachable!("results are built from object literals"),
    }
}
