#[test]
fn blank_and_unknown_lines_are_invalid_requests() {
    let mut s = Service::new();
    for line in ["", "[]", "{\"Command\": 1}", "{\"Command\": \"Nope\"}"] {
        let r: Value = serde_json::from_str(&s.handle_line(line.as_bytes())).unwrap();
        assert_eq!(code(&r), "InvalidRequest", "line {line:?}");
    }
    let r: Value = serde_json::from_str(&s.handle_line(&[0xff])).unwrap();
    assert_eq!(code(&r), "InvalidRequest");
}

#[test]
fn send_receive_delete_round_trip() {
    let mut s = Service::new();
    run(&mut s, json!({"Command": "CreateQueue", "QueueName": "jobs"}));
    let sent = run(&mut s, json!({"Command": "SendMessage", "QueueName": "jobs", "Body": "hi"}));
    assert_eq!(sent, json!({"ok": true, "MessageId": "m-1"}));
    let got = run(&mut s, json!({"Command": "ReceiveMessage", "QueueName": "jobs"}));
    assert_eq!(
        got["Messages"],
        json!([{"MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "hi",
                "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 0}])
    );
    let bad = run(&mut s, json!({"Command": "DeleteMessage", "QueueName": "jobs", "ReceiptHandle": "r-01"}));
    assert_eq!(code(&bad), "ReceiptHandleInvalid");
    let del = run(&mut s, json!({"Command": "DeleteMessage", "QueueName": "jobs", "ReceiptHandle": "r-1"}));
    assert_eq!(del, json!({"ok": true}));
    let again = run(&mut s, json!({"Command": "DeleteMessage", "QueueName": "jobs", "ReceiptHandle": "r-1"}));
    assert_eq!(code(&again), "ReceiptHandleExpired");
}

